// SPDX-License-Identifier: MIT
pragma solidity 0.8.9;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/ZeusPet.sol";

contract ZeusPetPrivilegeTest is Test {
    ZeusPet token;
    address owner = address(0xABCD);
    address attacker = address(0x1337);
    address initialMarketingWallet = address(0x999);

    function setUp() public {
        vm.prank(owner);
        token = new ZeusPet(300, 200, initialMarketingWallet);
    }

    function test_MarketingWallet_Escalation() public {
        // Verify initial marketing wallet setup
        assertTrue(token.excludeFromFee(initialMarketingWallet));
        assertEq(token.marketingWallet(), initialMarketingWallet);

        // Attack scenario - owner compromised
        vm.startPrank(owner);
        token.setMarketingWallet(attacker);
        vm.stopPrank();

        // Verify attacker wallet becomes fee-excluded
        assertTrue(token.excludeFromFee(attacker));
        assertEq(token.marketingWallet(), attacker);
    }

    function test_FeeExclusion_Escalation() public {
        // Verify attacker initially not fee-excluded
        assertFalse(token.excludeFromFee(attacker));

        // Attack scenario - owner compromised
        vm.startPrank(owner);
        token.setExcludeFromFee(attacker, true);
        vm.stopPrank();

        // Verify attacker now excluded from fees
        assertTrue(token.excludeFromFee(attacker));
    }
}
